// 월별 매출 데이터 (예: 라인차트, 바차트 등에서 사용)
export async function fetchMonthlySales(ym) {
  // ym은 무시하고 고정 데이터
  return [
    { ym: "2025-01", totalSales: 1230000 },
    { ym: "2025-02", totalSales: 1500000 },
    { ym: "2025-03", totalSales: 990000 },
    { ym: "2025-04", totalSales: 1710000 },
  ];
}

export async function fetchMonthlyRevenue(ym) {
  return fetchMonthlySales(ym);
}

